function reviewVisibleMethods(target,context,pathReference=null){
 const anchor=document.getElementById('visible-target-start-error');if(!anchor)return;
 const panel=document.createElement('section');panel.className='rule-block';panel.innerHTML='<h3>公开教程</h3><p class="small muted">教程与当前目标版本一致时才可选用。独立尝试保留在下方。</p><button class="ghost" id="visible-target-practices">查看该目标的公开实践</button><button class="ghost" id="visible-method-load">查看公开教程</button><button class="ghost" id="visible-method-contribute">贡献教程</button><p id="visible-method-status" class="small muted" role="status"></p><div id="visible-method-results"></div>';anchor.before(panel);
 panel.querySelector('#visible-target-practices').addEventListener('click',()=>{if(panel.isConnected)reviewOpenTargetPractices(target,context)});panel.querySelector('#visible-method-contribute').addEventListener('click',()=>{if(panel.isConnected)reviewContributeVisible(target,context)});
 const ownButton=document.createElement('button');ownButton.className='ghost';ownButton.textContent='我在这里的教程';panel.append(ownButton);const ownResults=document.createElement('div');panel.append(ownResults);
 ownButton.addEventListener('click',async()=>{if(!ownButton.isConnected||ownButton.disabled)return;ownButton.disabled=true;try{const r=await reviewKnowledgeRequest('/api/tutorials?nodeId='+encodeURIComponent(target.nodeId)+'&treeId='+encodeURIComponent(target.treeId),{context});if(!ownButton.isConnected||!reviewContextCurrent(context))return;const items=r.tutorials.filter(t=>t.authorId===context.ownerId);ownResults.innerHTML='<h3 style="margin-top:18px">我的教程</h3>'+items.map((t,i)=>`<details class="method"><summary>${esc(t.title)} · ${t.visibility==='public'?'公开':'私人'}</summary><div class="method-body"><p class="pre">${esc(t.method)}</p><p class="pre small">五分钟：${esc(t.startAction)}</p>${(t.resources||[]).map(a=>`<p><a href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">${esc(a.label)}</a> · ${a.optional?'可选':'所需'}${a.affiliate?' · 分成外链':''}</p>`).join('')}<p class="pre small">当时目标：${esc(t.targetSnapshot?.goal||'旧教程尚未绑定目标版本')}</p>${t.targetSnapshot?.version===target.version?`<button class="ghost" data-own-visible-method="${i}">修订这份教程</button>`:'<p class="small muted">原目标版本保留；为当前目标贡献教程请另建。</p>'}</div></details>`).join('')+(items.length?'':'<p class="small muted">本人尚未在这里保存教程。</p>');ownResults.querySelectorAll('[data-own-visible-method]').forEach(b=>b.addEventListener('click',()=>{if(b.isConnected)reviewContributeVisible(target,context,items[Number(b.dataset.ownVisibleMethod)])}))}catch(e){if(ownResults.isConnected&&reviewContextCurrent(context))ownResults.textContent=e.message}finally{ownButton.disabled=false}});
 const load=panel.querySelector('#visible-method-load'),status=panel.querySelector('#visible-method-status'),results=panel.querySelector('#visible-method-results');
 load.addEventListener('click',async()=>{if(!load.isConnected||load.disabled)return;load.disabled=true;status.textContent='正在核对当前目标的公开教程…';
  try{const r=await reviewKnowledgeRequest('/api/review-visible-targets/tutorials?nodeId='+encodeURIComponent(target.nodeId),{context});if(!load.isConnected||!reviewContextCurrent(context))return;if(r.ownerId!==context.ownerId||JSON.stringify(r.target)!==JSON.stringify(target)||!Array.isArray(r.tutorials))throw Error('目标版本已变化，请返回公开目标重新核对。');
   status.textContent=r.tutorials.length?`当前版本有 ${r.tutorials.length} 份公开教程。`:'当前版本暂无已绑定的公开教程，可先独立尝试。';
   results.innerHTML=r.tutorials.map((t,i)=>`<details class="method"><summary>${esc(t.title)}<br><span class="small muted">${esc(t.authorName)} · 教程 ${esc(t.version.slice(0,8))}</span></summary><div class="method-body"><p class="pre">${esc(t.method)}</p><h4>下一段五分钟</h4><p class="pre">${esc(t.startAction)}</p>${t.resources.map(a=>`<p><a href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">${esc(a.label)}</a> <span class="small muted">${a.optional?'可选材料':'所需材料'}${a.affiliate?' · 分成外链':''}</span></p>`).join('')}<button class="primary" data-visible-method-index="${i}">按此教程开始</button></div></details>`).join('');
   results.querySelectorAll('[data-visible-method-index]').forEach(b=>b.addEventListener('click',()=>reviewStartVisibleMethod(target,r.tutorials[Number(b.dataset.visibleMethodIndex)],context,b,status,pathReference)));
  }catch(e){if(load.isConnected&&reviewContextCurrent(context))status.textContent=e.message}finally{load.disabled=false}
 });
}
async function reviewStartVisibleMethod(target,tutorial,context,button,status,pathReference=null){
 if(!button.isConnected||button.disabled)return;button.disabled=true;
 try{const r=await reviewKnowledgeRequest('/api/review-visible-targets/tutorials?nodeId='+encodeURIComponent(target.nodeId),{context});if(!button.isConnected||!reviewContextCurrent(context))return;const current=r.tutorials?.find(t=>t.id===tutorial.id&&t.version===tutorial.version);if(r.ownerId!==context.ownerId||JSON.stringify(r.target)!==JSON.stringify(target)||JSON.stringify(current)!==JSON.stringify(tutorial))throw Error('目标或教程已修订、撤回，请重新读取后选择。');
  closeModal();start(target.title,{knowledge:{...(pathReference?{pathReference:clone(pathReference)}:{}),practiceMode:'visible-tutorial',nodeId:target.nodeId,nodeTitle:target.title,nodeGoal:target.goal,nodeFive:target.five,nodeVersion:target.sourceVersion,nodeDomain:target.domain,nodeBranch:target.branch,nodeOwnership:target.ownership,nodeVisibility:'public',methodId:'visible-service-'+tutorial.id+'-'+tutorial.version,methodTitle:tutorial.title,version:1,content:tutorial.method,resource:'',resourceLinks:clone(tutorial.resources),five:tutorial.startAction,methodAuthor:tutorial.authorName,serviceReference:{id:tutorial.id,version:tutorial.version,authorId:tutorial.authorId,authorName:tutorial.authorName},targetServiceReference:{nodeId:target.nodeId,treeId:target.treeId,targetVersion:target.version,sourceVersion:target.sourceVersion,ownerId:target.ownerId}}});toast('本次实践已保留所选教程、作者、材料和目标版本。');
 }catch(e){if(button.isConnected&&reviewContextCurrent(context))status.textContent=e.message}finally{button.disabled=false}
}
